  "Menu_ProcessGridInput": {
    returnType: "s8",
    params: "void",
    callsTo: ["ChangeGridMenuCursorPosition","GetLRKeysPressed","JOY_NEW","PlaySE"],
    lineCount: 35,
    bodyC: "u8 oldPos = sMenu.cursorPos;\n\n    if (JOY_NEW(A_BUTTON))\n    {\n        PlaySE(SE_SELECT);\n        return sMenu.cursorPos;\n    }\n    else if (JOY_NEW(B_BUTTON))\n    {\n        return MENU_B_PRESSED;\n    }\n    else if (JOY_NEW(DPAD_UP))\n    {\n        if (oldPos != ChangeGridMenuCursorPosition(0, -1))\n            PlaySE(SE_SELECT);\n        return MENU_NOTHING_CHOSEN;\n    }\n    else if (JOY_NEW(DPAD_DOWN))\n    {\n        if (oldPos != ChangeGridMenuCursorPosition(0, 1))\n            PlaySE(SE_SELECT);\n        return MENU_NOTHING_CHOSEN;\n    }\n    else if (JOY_NEW(DPAD_LEFT) || GetLRKeysPressed() == MENU_L_PRESSED)\n    {\n        if (oldPos != ChangeGridMenuCursorPosition(-1, 0))\n            PlaySE(SE_SELECT);\n        return MENU_NOTHING_CHOSEN;\n    }\n    else if (JOY_NEW(DPAD_RIGHT) || GetLRKeysPressed() == MENU_R_PRESSED)\n    {\n        if (oldPos != ChangeGridMenuCursorPosition(1, 0))\n            PlaySE(SE_SELECT);\n        return MENU_NOTHING_CHOSEN;\n    }\n\n    return MENU_NOTHING_CHOSEN;",
  },
  "Menu_ProcessInput": {
    returnType: "s8",
    params: "void",
    callsTo: ["JOY_NEW","Menu_MoveCursor","PlaySE"],
    lineCount: 23,
    bodyC: "if (JOY_NEW(A_BUTTON))\n    {\n        if (!sMenu.APressMuted)\n            PlaySE(SE_SELECT);\n        return sMenu.cursorPos;\n    }\n    else if (JOY_NEW(B_BUTTON))\n    {\n        return MENU_B_PRESSED;\n    }\n    else if (JOY_NEW(DPAD_UP))\n    {\n        PlaySE(SE_SELECT);\n        Menu_MoveCursor(-1);\n        return MENU_NOTHING_CHOSEN;\n    }\n    else if (JOY_NEW(DPAD_DOWN))\n    {\n        PlaySE(SE_SELECT);\n        Menu_MoveCursor(1);\n        return MENU_NOTHING_CHOSEN;\n    }\n\n    return MENU_NOTHING_CHOSEN;",
  },
  "Menu_ProcessInputNoWrap": {
    returnType: "s8",
    params: "void",
    callsTo: ["JOY_NEW","Menu_MoveCursorNoWrapAround","PlaySE"],
    lineCount: 24,
    bodyC: "u8 oldPos = sMenu.cursorPos;\n\n    if (JOY_NEW(A_BUTTON))\n    {\n        if (!sMenu.APressMuted)\n            PlaySE(SE_SELECT);\n        return sMenu.cursorPos;\n    }\n    else if (JOY_NEW(B_BUTTON))\n    {\n        return MENU_B_PRESSED;\n    }\n    else if (JOY_NEW(DPAD_UP))\n    {\n        if (oldPos != Menu_MoveCursorNoWrapAround(-1))\n            PlaySE(SE_SELECT);\n        return MENU_NOTHING_CHOSEN;\n    }\n    else if (JOY_NEW(DPAD_DOWN))\n    {\n        if (oldPos != Menu_MoveCursorNoWrapAround(1))\n            PlaySE(SE_SELECT);\n        return MENU_NOTHING_CHOSEN;\n    }\n\n    return MENU_NOTHING_CHOSEN;",
  },
  "Menu_ProcessInputNoWrapAround_other": {
    returnType: "s8",
    params: "void",
    callsTo: ["JOY_NEW","JOY_REPEAT","Menu_MoveCursorNoWrapAround","PlaySE"],
    lineCount: 24,
    bodyC: "u8 oldPos = sMenu.cursorPos;\n\n    if (JOY_NEW(A_BUTTON))\n    {\n        if (!sMenu.APressMuted)\n            PlaySE(SE_SELECT);\n        return sMenu.cursorPos;\n    }\n    else if (JOY_NEW(B_BUTTON))\n    {\n        return MENU_B_PRESSED;\n    }\n    else if (JOY_REPEAT(DPAD_ANY) == DPAD_UP)\n    {\n        if (oldPos != Menu_MoveCursorNoWrapAround(-1))\n            PlaySE(SE_SELECT);\n        return MENU_NOTHING_CHOSEN;\n    }\n    else if (JOY_REPEAT(DPAD_ANY) == DPAD_DOWN)\n    {\n        if (oldPos != Menu_MoveCursorNoWrapAround(1))\n            PlaySE(SE_SELECT);\n        return MENU_NOTHING_CHOSEN;\n    }\n\n    return MENU_NOTHING_CHOSEN;",
  },
