    returnType: "void",
    params: "u8 windowId, u8 fontId, u8 left, u8 top, u8 letterSpacing, u8 lineHeight, u8 itemCount, const struct MenuAction *menuActions, const u8 *actionIds",
    callsTo: ["AddTextPrinter","CopyWindowToVram","GetFontAttribute"],
    lineCount: 20,
    bodyC: "u8 i;\n    struct TextPrinterTemplate printer;\n\n    printer.windowId = windowId;\n    printer.fontId = fontId;\n    printer.fgColor = GetFontAttribute(fontId, FONTATTR_COLOR_FOREGROUND);\n    printer.bgColor = GetFontAttribute(fontId, FONTATTR_COLOR_BACKGROUND);\n    printer.shadowColor = GetFontAttribute(fontId, FONTATTR_COLOR_SHADOW);\n    printer.unk = GetFontAttribute(fontId, FONTATTR_UNKNOWN);\n    printer.letterSpacing = letterSpacing;\n    printer.lineSpacing = GetFontAttribute(fontId, FONTATTR_LINE_SPACING);\n    printer.x = left;\n    printer.currentX = left;\n\n    for (i = 0; i < itemCount; i++)\n    {\n        printer.currentChar = menuActions[actionIds[i]].text;\n        printer.y = (lineHeight * i) + top;\n        printer.currentY = printer.y;\n        AddTextPrinter(&printer, TEXT_SKIP_DRAW, NULL);\n    }\n\n    CopyWindowToVram(windowId, COPYWIN_GFX);",
